package org.sormus.downloads;
import java.net.URI;
public final class TransferProtocol {
 public static String server(String value)throws Exception {URI u=new URI(value.trim());String host=u.getHost();if(!"http".equals(u.getScheme())||host==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!(u.getPath().isEmpty()||u.getPath().equals("/")))throw new Exception("Enter the PC's numeric LAN address, for example http://192.168.1.10:7041");String[] p=host.split("\\.");if(p.length!=4)throw new Exception("Use the PC's numeric LAN address.");int[] n=new int[4];for(int i=0;i<4;i++){if(!p[i].matches("0|[1-9][0-9]{0,2}"))throw new Exception("Invalid PC address.");n[i]=Integer.parseInt(p[i]);if(n[i]>255)throw new Exception("Invalid PC address.");}if(!(n[0]==10||n[0]==172&&n[1]>=16&&n[1]<=31||n[0]==192&&n[1]==168||n[0]==127))throw new Exception("Use a local network PC address.");int port=u.getPort();if(port==0||port>65535)throw new Exception("Invalid PC port.");return "http://"+host+(port<0?"":":"+port);}
 public static boolean link(String text){if(text==null||text.length()>8192||text.matches("(?s).*[\\x00-\\x20\\x7f].*"))return false;try{URI u=new URI(text);return "magnet".equalsIgnoreCase(u.getScheme())||("http".equalsIgnoreCase(u.getScheme())||"https".equalsIgnoreCase(u.getScheme()))&&u.getHost()!=null&&u.getUserInfo()==null;}catch(Exception e){return false;}}
}
